/**
 * Resolved on-sheet placement in EMU: the anchor rectangle for
 * top-level drawings, the group-mapped (rotation/flip aware)
 * rectangle for group children.
 */
export type RectEmu = { xEmu: number; yEmu: number; widthEmu: number; heightEmu: number }

type DrawingNode = DrawingMeta & DrawingPlacement & { drawingPath: number[]; absoluteRectEmu: RectEmu }

export type DrawnImage = DrawingNode & { kind: 'image'; image: DrawingImage }
export type DrawnChart = DrawingNode & { kind: 'chart'; chart: JsChart }
export type DrawnChartEx = DrawingNode & { kind: 'chartEx'; chartEx: JsChartEx }
export type DrawnFormControl = DrawingNode & { kind: 'formControl'; formControl: FormControlPayload }
export type DrawnComment = DrawingNode & { kind: 'comment'; comment: DrawingComment }
export type DrawnShape = DrawingNode & { kind: 'shape'; shape: DrawingShape }
export type DrawnGroup = DrawingNode & { kind: 'group'; group: { groupTransform: DrawingGroupTransform; children: Drawing[] } }
export type DrawnRaw = DrawingNode & { kind: 'raw'; raw: RawDrawingMetadata }

export type Drawing = DrawnImage | DrawnChart | DrawnChartEx | DrawnFormControl | DrawnComment | DrawnShape | DrawnGroup | DrawnRaw

type DrawingInputPayload =
  | { kind: 'image'; image: DrawingImageInput }
  | { kind: 'chart'; chart: ChartInput }
  | { kind: 'chartEx'; chartEx: ChartExInput }
  | { kind: 'formControl'; formControl: FormControlInputPayload }
  | { kind: 'comment'; comment: DrawingComment }
  | { kind: 'shape'; shape: DrawingShapeInput }
  | { kind: 'group'; group: { groupTransform?: DrawingGroupTransform; children?: DrawingInput[] } }

export type TopLevelDrawingInput = DrawingMetaInput & {
  anchor: DrawingAnchor
  transform?: never
} & DrawingInputPayload

export type GroupChildDrawingInput = DrawingMetaInput & {
  anchor?: never
  transform: DrawingChildTransform
} & DrawingInputPayload

export type DrawingInput = TopLevelDrawingInput | GroupChildDrawingInput

export interface FormControlInteractionResult {
  controlsChanged: number
  linkedCellsChanged: number
}

type ReplacedWorksheetMembers =
  | 'drawings'
  | 'charts'
  | 'chartCount'
  | 'chartsEx'
  | 'chartExCount'
  | 'images'
  | 'imageCount'
  | 'formControls'
  | 'formControlCount'
  | 'addFormControl'
  | 'setFormControl'
  | 'removeFormControl'
  | 'addDrawing'
  | 'insertDrawing'
  | 'setDrawing'
  | 'removeDrawing'
  | 'moveDrawing'
  | 'drawingImageData'
  | 'drawingSvgData'
  | 'setFormControlCheckState'

export type Worksheet = Omit<Generated.Worksheet, ReplacedWorksheetMembers> & {
  /** Iterate over sparse rows, batching native calls internally. */
  iterateRows(opts?: JsRowsOptions): RowIterator
  readonly drawings: Drawing[]
  readonly formControls: DrawnFormControl[]
  readonly formControlCount: number
  readonly images: DrawnImage[]
  readonly imageCount: number
  readonly charts: DrawnChart[]
  readonly chartCount: number
  readonly chartsEx: DrawnChartEx[]
  readonly chartExCount: number
  addDrawing(input: TopLevelDrawingInput): number
  /** Drawing paths are positional; mutating the list invalidates previously returned paths. */
  insertDrawing(index: number, input: TopLevelDrawingInput): void
  /** Drawing paths are positional; mutating the list invalidates previously returned paths. */
  setDrawing(path: number[], input: DrawingInput): void
  /** Drawing paths are positional; mutating the list invalidates previously returned paths. */
  removeDrawing(path: number[]): void
  /** Drawing paths are positional; mutating the list invalidates previously returned paths. */
  moveDrawing(from: number, to: number): void
  /** Paths are positional; mutating the drawing list invalidates previously returned paths. */
  drawingImageData(path: number[]): Buffer
  /** Paths are positional; mutating the drawing list invalidates previously returned paths. */
  drawingSvgData(path: number[]): Buffer | null
  setFormControlCheckState(path: number[], state: Generated.JsCheckState): FormControlInteractionResult
}

